import React, { useState, useMemo } from 'react';
import AnimatedPage from '../../layouts/AnimatedPage';
import { appColors } from '../../theme/appColors';
import {
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  FormControl,
  Grid,
  TextField,
  Typography,
  MenuItem,
  Select,
  Checkbox,
  ListItemText,
  SelectChangeEvent,
} from '@mui/material';
import SendIcon from '@mui/icons-material/Send';
import { useGetAllBranchQuery, useSendMessageMutation } from '../posApi';
import { useNotifier } from '../../core/Notifier';
import { IBranchDetails } from '../../core/Interface/branch.interface';
import { useTranslation } from 'react-i18next';

const Message = () => {
  const { showErrorMessage, showMessage } = useNotifier();
  const [selectedBranches, setSelectedBranches] = useState<string[]>([]);
  const [messageContent, setMessageContent] = useState<string>('');
  const { t } = useTranslation(['message']);

  const [sendMessage, { isLoading: isSending }] = useSendMessageMutation();

  const { data } = useGetAllBranchQuery({
    pageIndex: 0,
    pageSize: 50,
    searchText: '',
  });

  const branches = useMemo(() => {
    if (data?.data) {
      return (data.data as IBranchDetails).records || [];
    }
    return [];
  }, [data]);

  const handleBranchChange = (event: SelectChangeEvent<string[]>) => {
    setSelectedBranches(event.target.value as string[]);
  };

  const handleSendMessage = async () => {
    if (!messageContent.trim() || selectedBranches.length === 0) {
      showErrorMessage(
        'Please enter a message and select at least one branch.'
      );
      return;
    }
    try {
      const payload = {
        branchIds: selectedBranches,
        message: messageContent.trim(),
      };
      const response = await sendMessage(payload).unwrap();
      if (response?.status) {
        showMessage(response.message);
        setSelectedBranches([]);
        setMessageContent('');
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };
  

  return (
    <AnimatedPage>
      <Box
        sx={{
          backgroundColor: appColors.greenSmoke,
          width: '100%',
          height: '100%',
        }}
      >
        <Card
          sx={{
            borderRadius: '2px',
            pb: '10px',
            maxWidth: '100%',
            boxShadow: '0 0 10px #ccc;',
          }}
        >
          <CardContent sx={{ m: 0 }}>
            <Grid
              alignItems="center"
              container
              justifyContent="flex-start"
              spacing={2}
              sx={{ padding: '5px' }}
            >
              <Grid
                item
                lg={3}
                md={8}
                sm={6}
                xs={8}
              >
                <Typography
                  sx={{
                    fontWeight: 400,
                    fontSize: '1rem',
                    letterSpacing: '0.32px',
                    pb: 1,
                  }}
                  variant="subtitle1"
                >
                  {t('message:selectBranches')}
                </Typography>

                <FormControl sx={{ width: '100%' }}>
                  <Select
                    multiple
                    onChange={handleBranchChange}
                    renderValue={(selected) =>
                      selected
                        .map((id) => {
                          const branch = branches.find((b) => b.id === id);
                          return branch ? branch.name : id;
                        })
                        .join(', ')
                    }
                    value={selectedBranches}
                  >
                    {branches.map((branch) => (
                      <MenuItem
                        key={branch.id}
                        value={branch.id}
                      >
                        <Checkbox
                          checked={selectedBranches.includes(branch.id)}
                        />
                        <ListItemText primary={branch.name} />
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>

              <Grid
                item
                lg={6}
                md={12}
                sm={6}
                xs={12}
              >
                {/* <TextField
                  placeholder="MultiLine with rows: 2 and rowsMax: 4"
                  multiline
                  rows={2}
                  maxRows={4}
                  fullWidth
                /> */}
              </Grid>

              <Grid
                item
                lg={6}
                md={12}
                sm={6}
                xs={12}
              >
                <Typography
                  sx={{
                    fontWeight: 400,
                    fontSize: '1rem',
                    letterSpacing: '0.32px',
                    pb: 1,
                  }}
                  variant="subtitle1"
                >
                  {t('message:messageText')}
                </Typography>
                <TextField
                  fullWidth
                  maxRows={6}
                  multiline
                  onChange={(e) => setMessageContent(e.target.value)}
                  placeholder={t('message:typeYourMsg')}
                  rows={4}
                  value={messageContent}
                />
              </Grid>
            </Grid>
            <Grid
              item
              sx={{
                display: 'flex',
                justifyContent: 'end',
                alignItems: 'end',
                pt: 2,
              }}
              xs={2}
            >
              <Button
                disabled={isSending}
                endIcon={<SendIcon />}
                onClick={handleSendMessage}
                sx={{
                  borderRadius: '5px',
                  background: appColors.reflexBlue[100],
                  color: appColors.white,
                  height: '40px',
                  width: 'auto',
                }}
                variant="contained"
              >
                {false && (
                  <Box sx={{ pr: 2, pt: 0.5 }}>
                    <CircularProgress
                      size={16}
                      sx={{ color: 'white' }}
                    />
                  </Box>
                )}{' '}
                {t('message:send')}
              </Button>
            </Grid>
          </CardContent>
        </Card>
      </Box>
    </AnimatedPage>
  );
};

export default Message;
